CREATE TABLE IF NOT EXISTS orgs ( id INTEGER PRIMARY KEY AUTOINCREMENT, nome TEXT NOT NULL, cnpj TEXT, email TEXT, pix_chave TEXT, pix_nome TEXT, pix_cidade TEXT, instrucoes_pagamento TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS users ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL REFERENCES orgs(id), nome TEXT NOT NULL, email TEXT NOT NULL UNIQUE, senha_hash TEXT NOT NULL, papel TEXT NOT NULL DEFAULT 'consultor', ativo INTEGER NOT NULL DEFAULT 1, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS sessions ( token TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id), expires_at TEXT NOT NULL );
CREATE TABLE IF NOT EXISTS clientes ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL REFERENCES orgs(id), razao_social TEXT NOT NULL, nome_fantasia TEXT, cnpj TEXT, email_financeiro TEXT, telefone TEXT, endereco TEXT, cidade TEXT, uf TEXT, cep TEXT, sponsor_nome TEXT, sponsor_email TEXT, sponsor_telefone TEXT, status TEXT NOT NULL DEFAULT 'ativo', asaas_customer_id TEXT, observacoes TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS ix_clientes_org ON clientes(org_id, status);
CREATE TABLE IF NOT EXISTS servicos ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL REFERENCES orgs(id), nome TEXT NOT NULL, descricao TEXT, valor_padrao REAL, produto TEXT, ativo INTEGER NOT NULL DEFAULT 1 );
CREATE TABLE IF NOT EXISTS contratos ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL REFERENCES orgs(id), cliente_id INTEGER NOT NULL REFERENCES clientes(id), servico_id INTEGER REFERENCES servicos(id), codigo TEXT NOT NULL, objeto TEXT NOT NULL, modalidade TEXT NOT NULL DEFAULT 'mensal', valor REAL NOT NULL, parcelas INTEGER DEFAULT 1, dia_vencimento INTEGER DEFAULT 10, data_inicio TEXT NOT NULL, data_fim TEXT, primeiro_vencimento TEXT, status TEXT NOT NULL DEFAULT 'ativo', sponsor_nome TEXT, sponsor_email TEXT, observacoes TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS ix_contratos_cli ON contratos(org_id, cliente_id);
CREATE TABLE IF NOT EXISTS faturas ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL REFERENCES orgs(id), contrato_id INTEGER NOT NULL REFERENCES contratos(id), cliente_id INTEGER NOT NULL REFERENCES clientes(id), numero TEXT NOT NULL, competencia TEXT NOT NULL, parcela INTEGER, total_parcelas INTEGER, descricao TEXT, valor REAL NOT NULL, vencimento TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'aberta', boleto_provider TEXT, boleto_id TEXT, boleto_url TEXT, linha_digitavel TEXT, pix_copia_cola TEXT, emitida_em TEXT, enviada_em TEXT, pago_em TEXT, valor_pago REAL, forma_pagamento TEXT, obs_baixa TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE UNIQUE INDEX IF NOT EXISTS ux_faturas_numero ON faturas(org_id, numero);
CREATE INDEX IF NOT EXISTS ix_faturas_comp ON faturas(org_id, competencia);
CREATE INDEX IF NOT EXISTS ix_faturas_venc ON faturas(org_id, vencimento, status);
CREATE INDEX IF NOT EXISTS ix_faturas_contrato ON faturas(contrato_id, competencia, parcela);
CREATE TABLE IF NOT EXISTS projetos ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER NOT NULL REFERENCES orgs(id), contrato_id INTEGER NOT NULL REFERENCES contratos(id), cliente_id INTEGER NOT NULL REFERENCES clientes(id), produto TEXT NOT NULL, titulo TEXT NOT NULL, unidade TEXT, sponsor_nome TEXT NOT NULL, sponsor_email TEXT NOT NULL, sponsor_token TEXT NOT NULL UNIQUE, prazo TEXT, status TEXT NOT NULL DEFAULT 'aberto', enviado_em TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS campanhas ( id INTEGER PRIMARY KEY AUTOINCREMENT, projeto_id INTEGER NOT NULL REFERENCES projetos(id), org_id INTEGER NOT NULL REFERENCES orgs(id), instrumento TEXT NOT NULL, token TEXT NOT NULL UNIQUE, meta_respostas INTEGER, created_at TEXT DEFAULT (datetime('now')) );
CREATE TABLE IF NOT EXISTS respostas ( id INTEGER PRIMARY KEY AUTOINCREMENT, campanha_id INTEGER NOT NULL REFERENCES campanhas(id), perfil TEXT, respostas TEXT, created_at TEXT DEFAULT (datetime('now')) );
CREATE INDEX IF NOT EXISTS ix_respostas_camp ON respostas(campanha_id);
CREATE TABLE IF NOT EXISTS eventos ( id INTEGER PRIMARY KEY AUTOINCREMENT, org_id INTEGER, user_id INTEGER, tipo TEXT NOT NULL, ref TEXT, detalhe TEXT, created_at TEXT DEFAULT (datetime('now')) );
